"""Typical spending (R-1.9, stage 6): purchases generated by a fixed rule, no randomness.

n purchases in a typical week and an average round-up of a cents. Weeks are calendar weeks, Monday first. Purchase k of n (k = 0..n-1) of every
week is dated Monday + floor(7*k / n) days. Each is a posted debit purchase of 1200 + (100 - a) cents, so its round-up (R-2.1) is exactly a.
A purchase counts only if its date is inside [start, end] (R-1.6). The pattern depends only on the calendar, never on the start date.
"""

import re
from datetime import date, timedelta

BASE_CENTS = 1200            # every typical purchase is $12.xx
DESCRIPTION = "Typical purchase"
_WHOLE = re.compile(r"^[0-9]{1,2}$")
_CENTS = re.compile(r"^0\.[0-9]{2}$")


def typical_transactions(per_week: int, average_cents: int, start: str, end: str) -> list[dict]:
    if isinstance(per_week, bool) or not isinstance(per_week, int) or not 1 <= per_week <= 60:
        raise ValueError("purchases per week must be a whole number from 1 to 60")
    if isinstance(average_cents, bool) or not isinstance(average_cents, int) or not 1 <= average_cents <= 99:
        raise ValueError("the average round-up must be from $0.01 to $0.99")
    first, last = date.fromisoformat(start), date.fromisoformat(end)
    amount_cents = BASE_CENTS + (100 - average_cents)
    amount = f"{amount_cents // 100}.{amount_cents % 100:02d}"
    out = []
    monday = first - timedelta(days=first.weekday())
    while monday <= last:
        for k in range(per_week):
            day = monday + timedelta(days=(7 * k) // per_week)
            if first <= day <= last:
                out.append({"posted_date": day.isoformat(), "amount": amount, "direction": "debit", "status": "posted",
                            "type": "", "category": "purchase", "description": DESCRIPTION})
        monday += timedelta(days=7)
    return out


def parse_typical(spec: dict, start: str, end: str) -> list[dict]:
    """`typical` from a scenario: {"per_week": "5", "average_roundup": "0.50"} (strings, strict)."""
    if not isinstance(spec, dict) or set(spec) != {"per_week", "average_roundup"}:
        raise ValueError("typical needs exactly per_week and average_roundup")
    pw, avg = spec["per_week"], spec["average_roundup"]
    if not isinstance(pw, str) or not _WHOLE.match(pw):
        raise ValueError("per_week must be a whole number written as text, 1 to 60")
    if not isinstance(avg, str) or not _CENTS.match(avg):
        raise ValueError("average_roundup must be written like 0.50")
    return typical_transactions(int(pw), int(avg[2:]), start, end)
